fd.rendered(function() {
    var parts = ['Street','City','PostalCode'];
    var copied = {Street:'',City:'',PostalCode:''};
    function syncAddress() {
        if (fd.field('SameAsBillingAddress').value !== true) return;
        parts.forEach(function(part) {
            var target = fd.field('Service' + part);
            var source = fd.field('Billing' + part).value || '';
            if (!target.value || target.value === copied[part]) target.value = source || null;
            copied[part] = source;
        });
    }
    fd.field('SameAsBillingAddress').$on('change', syncAddress);
    parts.forEach(function(part) { fd.field('Billing' + part).$on('change', syncAddress); });
    syncAddress();
});
